import logging
import socket
import time
from abc import ABCMeta, abstractmethod
from typing import Union

from ..exceptions import PduConnectionError, Timeout
from .base import PDU, PduIdentInfo, PduIdentificationType


class TcpPdu(PDU, metaclass=ABCMeta):
    """Class that makes it possible to
    manage a single PDU device over the TCP protocol."""

    IDN_QUERIES = ("*IDN?\r\n", "*IDN?\n", "*IDN?")

    def __init__(
        self,
        host: str,
        port: int,
        timeout: Union[float, int],
        retry_timeout: Union[float, int],
    ) -> None:
        super().__init__(host)
        self._port = port
        self._socket_timeout = float(timeout)
        self._retry_timeout = float(retry_timeout)
        self._buffer_size = 128
        self._encoding = "iso-8859-1"

    @abstractmethod
    def _build_command(self, port, status):
        """Build command for TCP-based PDU get/set status"""

    @abstractmethod
    def _parse_response(self, response):
        """Parser for response from PDU"""

    def _set_port_status(self, port, status):
        logging.info(f"TCP: Setting port to {status}: {port}")
        command = self._build_command(port, status=status)
        return self._execute_cmd_with_retry_on_timeout(command)

    def get_port_status(self, port):
        logging.info(f"TCP: Fetching status of port: {port}")
        command = self._build_command(port, status=None)
        try:
            response = self._execute_cmd_with_retry_on_timeout(command)
        except socket.error as e:
            logging.error(str(e))
            exc_msg = "Error getting port status, port: {}"
            exc_msg = exc_msg.format(port)
            raise PduConnectionError(exc_msg)
        parsed_response = self._parse_response(response)
        return self._reversed_port_settings[parsed_response]

    def _connect(self):
        conn = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        conn.settimeout(self._socket_timeout)
        try:
            log_msg = "Trying to connect to host={}, port={}"
            log_msg = log_msg.format(self._host, self._port)
            logging.info(log_msg)
            conn.connect((self._host, self._port))
            return conn
        except socket.error as e:
            logging.error(str(e))
            exc_msg = "Cannot connect to PDU (host={}, port={})"
            exc_msg = exc_msg.format(self._host, self._port)
            raise PduConnectionError(exc_msg)

    def _execute_cmd_with_retry_on_timeout(self, tcp_msg):
        start = time.time()
        while time.time() - start < self._retry_timeout:
            reply = self._execute_cmd(tcp_msg)
            if reply != "":
                return reply
            warn_msg = "Socket connection timed out. Reconnecting."
            logging.warning(warn_msg)
            time.sleep(2)
        raise Timeout("Socket connection timed out.")

    def _execute_cmd(self, tcp_msg):
        logging.debug(f"Sending command to device: {tcp_msg.strip() if isinstance(tcp_msg, str) else tcp_msg}")
        conn = self._connect()

        if isinstance(tcp_msg, str):
            encoded_msg = tcp_msg.encode()
        else:
            encoded_msg = tcp_msg
        conn.send(encoded_msg)

        try:
            reply = conn.recv(self._buffer_size)
        except socket.timeout:
            reply = ""
        conn.shutdown(socket.SHUT_WR)
        conn.close()
        response = self._decode_reply(reply)
        logging.debug(f"Received reply: {response}")
        return response

    def _decode_reply(self, reply):
        if isinstance(reply, bytes):
            return reply.decode(self._encoding)
        else:
            return reply

    def get_pdu_info(self) -> PduIdentInfo:
        """Return identification info using SCPI `*IDN?` when available.

        Tries common line endings in order defined by `IDN_QUERIES`.
        """
        for cmd in self.IDN_QUERIES:
            try:
                response = self._execute_cmd_with_retry_on_timeout(cmd)
            except Exception:
                continue
            if isinstance(response, str):
                s = response.strip()
                if s:
                    return PduIdentInfo(identifier=s, identification_type=PduIdentificationType.SCPI_IDN)
        return PduIdentInfo(identifier="UNKNOWN", identification_type=PduIdentificationType.NOT_IMPLEMENTED)
